// Formula parser and evaluator. AST nodes: num, str, bool, err, ref, range, un, bin, call.
import { parseAddr, toAddr } from "./addr.mjs";

const REF_RE = /(\$?[A-Za-z]{1,3}\$?[1-9]\d*)(?![A-Za-z0-9_.(])/y;
const NUM_RE = /(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/y;
const IDENT_RE = /[A-Za-z_][A-Za-z0-9_.]*/y;
const ERR_RE = /#(?:DIV\/0!|VALUE!|NAME\?|REF!|NUM!|ERROR!|CYCLE!)/y;
const NUMSTR_RE = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

function tokenize(text) {
  const toks = [];
  let i = 0;
  const sticky = (re) => { re.lastIndex = i; return re.exec(text); };
  while (i < text.length) {
    const ch = text[i];
    if (/\s/.test(ch)) { i++; continue; }
    let m;
    if (ch === '"') {
      let s = "", j = i + 1;
      for (;;) {
        if (j >= text.length) throw new SyntaxError("unterminated string");
        if (text[j] === '"') {
          if (text[j + 1] === '"') { s += '"'; j += 2; continue; }
          break;
        }
        s += text[j++];
      }
      toks.push({ t: "str", v: s });
      i = j + 1;
    } else if ((m = sticky(NUM_RE)) && !/[A-Za-z_]/.test(text[i + m[0].length] ?? "")) {
      toks.push({ t: "num", v: Number(m[0]) });
      i += m[0].length;
    } else if ((m = sticky(REF_RE))) {
      toks.push({ t: "ref", v: m[1] });
      i += m[0].length;
    } else if ((m = sticky(IDENT_RE))) {
      i += m[0].length;
      let j = i;
      while (/\s/.test(text[j] ?? "")) j++;
      const up = m[0].toUpperCase();
      if (text[j] === "(") { toks.push({ t: "fn", v: up }); i = j + 1; toks.push({ t: "(" }); }
      else if (up === "TRUE" || up === "FALSE") toks.push({ t: "bool", v: up === "TRUE" });
      else throw new SyntaxError(`unexpected name ${m[0]}`);
    } else if (ch === "#" && (m = sticky(ERR_RE))) {
      toks.push({ t: "err", v: m[0] });
      i += m[0].length;
    } else {
      const two = text.slice(i, i + 2);
      if (two === "<=" || two === ">=" || two === "<>") { toks.push({ t: "op", v: two }); i += 2; }
      else if ("=<>&+-*/^".includes(ch)) { toks.push({ t: "op", v: ch }); i++; }
      else if ("(),:".includes(ch)) { toks.push({ t: ch }); i++; }
      else throw new SyntaxError(`unexpected character ${ch}`);
    }
  }
  return toks;
}

const normRef = (s) => { const a = parseAddr(s); return toAddr(a.col, a.row); };

export function parseFormula(text) {
  const toks = tokenize(text);
  let p = 0;
  const peek = () => toks[p];
  const isOp = (...ops) => peek()?.t === "op" && ops.includes(peek().v);
  const expect = (t) => { if (peek()?.t !== t) throw new SyntaxError(`expected ${t}`); return toks[p++]; };

  const binary = (next, ops) => () => {
    let l = next();
    while (isOp(...ops)) { const op = toks[p++].v; l = { t: "bin", op, l, r: next() }; }
    return l;
  };
  function primary() {
    const k = toks[p++];
    if (!k) throw new SyntaxError("unexpected end");
    switch (k.t) {
      case "num": return { t: "num", v: k.v };
      case "str": return { t: "str", v: k.v };
      case "bool": return { t: "bool", v: k.v };
      case "err": return { t: "err", v: k.v };
      case "ref": {
        if (peek()?.t === ":") { p++; const b = expect("ref"); return { t: "range", a: normRef(k.v), b: normRef(b.v) }; }
        return { t: "ref", addr: normRef(k.v) };
      }
      case "(": { const e = comparison(); expect(")"); return e; }
      case "fn": {
        expect("(");
        const args = [];
        if (peek()?.t === ")") p++;
        else {
          for (;;) {
            args.push(comparison());
            if (peek()?.t === ",") { p++; continue; }
            expect(")");
            break;
          }
        }
        return { t: "call", name: k.v, args };
      }
      default: throw new SyntaxError(`unexpected ${k.t}`);
    }
  }
  function unary() {
    if (isOp("-", "+")) { const op = toks[p++].v; return { t: "un", op, x: unary() }; }
    return primary();
  }
  const power = binary(unary, ["^"]);
  const term = binary(power, ["*", "/"]);
  const sum = binary(term, ["+", "-"]);
  const concat = binary(sum, ["&"]);
  const comparison = binary(concat, ["=", "<>", "<", ">", "<=", ">="]);

  const ast = comparison();
  if (p < toks.length) throw new SyntaxError("unexpected trailing input");
  return ast;
}

function rangeAddrs(a, b) {
  const x = parseAddr(a), y = parseAddr(b);
  const out = [];
  for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++)
    for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++) out.push(toAddr(c, r));
  return out;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": for (const a of rangeAddrs(n.a, n.b)) seen.add(a); break;
      case "un": walk(n.x); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const fix = (n) => (Number.isFinite(n) ? (n === 0 ? 0 : n) : "#NUM!");

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number") return v;
  const t = v.trim();
  return NUMSTR_RE.test(t) ? Number(t) : "#VALUE!";
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
}

const toText = (v) => (v === null ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = [0, "", false][rank(b)];
  else if (b === null) b = [0, "", false][rank(a)];
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function roundHalfAway(x, d) {
  const abs = Math.abs(x);
  const s = String(abs);
  let r;
  if (s.includes("e")) r = Math.round(abs * 10 ** d) / 10 ** d;
  else r = Number(Math.round(Number(`${s}e${d}`)) + `e${-d}`);
  return x < 0 ? -r : r;
}

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": case "err": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const x = toNum(ev(n.x));
        if (typeof x === "string") return x;
        return fix(n.op === "-" ? -x : x);
      }
      case "bin": return binop(n);
      case "call": return call(n);
    }
  };

  function binop(n) {
    const lv = ev(n.l);
    if (isErr(lv)) return lv;
    const rv = ev(n.r);
    if (isErr(rv)) return rv;
    const op = n.op;
    if (op === "&") return toText(lv) + toText(rv);
    if (["=", "<>", "<", ">", "<=", ">="].includes(op)) {
      const c = compare(lv, rv);
      switch (op) {
        case "=": return c === 0;
        case "<>": return c !== 0;
        case "<": return c < 0;
        case ">": return c > 0;
        case "<=": return c <= 0;
        default: return c >= 0;
      }
    }
    const a = toNum(lv);
    if (typeof a === "string") return a;
    const b = toNum(rv);
    if (typeof b === "string") return b;
    switch (op) {
      case "+": return fix(a + b);
      case "-": return fix(a - b);
      case "*": return fix(a * b);
      case "/": return b === 0 ? "#DIV/0!" : fix(a / b);
      default: return fix(a ** b);
    }
  }

  // Flattens arguments into [{ v, direct }] entries, ranges row by row.
  const flat = (args) => {
    const out = [];
    for (const a of args) {
      if (a.t === "range") for (const ad of rangeAddrs(a.a, a.b)) out.push({ v: lookup(ad), direct: false });
      else out.push({ v: ev(a), direct: true });
    }
    return out;
  };

  function call(n) {
    const { name, args } = n;
    const len = args.length;
    const noRange = () => args.some((a) => a.t === "range");
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const nums = [];
        for (const { v, direct } of flat(args)) {
          if (isErr(v)) return v;
          if (direct) { const x = toNum(v); if (typeof x === "string") return x; nums.push(x); }
          else if (typeof v === "number") nums.push(v);
        }
        if (name === "SUM") return fix(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return nums.length ? fix(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return fix(name === "MIN" ? Math.min(...nums) : Math.max(...nums));
      }
      case "COUNT": return flat(args).filter(({ v }) => typeof v === "number").length;
      case "IF": {
        if ((len !== 2 && len !== 3) || noRange()) return "#VALUE!";
        const c = toBool(ev(args[0]));
        if (typeof c === "string") return c;
        if (c) return ev(args[1]);
        return len === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        if (!len) return "#VALUE!";
        const bools = [];
        for (const { v, direct } of flat(args)) {
          if (direct) { const b = toBool(v); if (typeof b === "string") return b; bools.push(b); }
          else if (typeof v === "number" || typeof v === "boolean") bools.push(toBool(v));
        }
        return name === "AND" ? bools.every(Boolean) : bools.some(Boolean);
      }
      case "NOT": {
        if (len !== 1 || noRange()) return "#VALUE!";
        const b = toBool(ev(args[0]));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (len !== 2 || noRange()) return "#VALUE!";
        const x = toNum(ev(args[0]));
        if (typeof x === "string") return x;
        const d = toNum(ev(args[1]));
        if (typeof d === "string") return d;
        return fix(roundHalfAway(x, Math.trunc(d)));
      }
      case "ABS": {
        if (len !== 1 || noRange()) return "#VALUE!";
        const x = toNum(ev(args[0]));
        return typeof x === "string" ? x : fix(Math.abs(x));
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (len !== 1 || noRange()) return "#VALUE!";
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let s = "";
        for (const { v } of flat(args)) { if (isErr(v)) return v; s += toText(v); }
        return s;
      }
      default: return "#NAME?";
    }
  }

  return ev(ast);
}
