import { parseAddr, compareAddr } from "./addr.mjs";
import { cellAddrs } from "./sheet.mjs";
import { parseFormula, refsOf, evaluate } from "./formula.mjs";

const NUMSTR_RE = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (NUMSTR_RE.test(t) && Number.isFinite(Number(t))) return Number(t);
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

// Parses every formula cell: Map addr -> { ast, deps } (ast null when it does not parse).
function analyze(sheet) {
  const info = new Map();
  for (const addr of cellAddrs(sheet)) {
    const raw = sheet.cells.get(addr);
    if (!raw.startsWith("=")) continue;
    try {
      const ast = parseFormula(raw.slice(1));
      info.set(addr, { ast, deps: refsOf(ast).filter((a) => sheet.cells.get(a)?.startsWith("=")) });
    } catch {
      info.set(addr, { ast: null, deps: [] });
    }
  }
  return info;
}

// Iterative Tarjan: returns SCCs, dependencies first.
function sccs(info) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], out = [];
  let counter = 0;
  for (const root of info.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const deps = info.get(v).deps;
      if (i < deps.length) {
        frame[1]++;
        const w = deps[i];
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const u = work[work.length - 1][0]; low.set(u, Math.min(low.get(u), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const cyclic = (comp, info) => comp.length > 1 || info.get(comp[0]).deps.includes(comp[0]);

export function computeAll(sheet) {
  const info = analyze(sheet);
  const vals = new Map();
  for (const addr of cellAddrs(sheet)) {
    const raw = sheet.cells.get(addr);
    if (!info.has(addr)) vals.set(addr, valueOf(raw));
  }
  const lookup = (a) => vals.get(a) ?? null;
  for (const comp of sccs(info)) {
    if (cyclic(comp, info)) { for (const a of comp) vals.set(a, "#CYCLE!"); continue; }
    const a = comp[0];
    const { ast } = info.get(a);
    vals.set(a, ast ? evaluate(ast, lookup) : "#ERROR!");
  }
  const out = new Map();
  for (const addr of cellAddrs(sheet)) out.set(addr, vals.get(addr));
  return out;
}

export function dependents(sheet, addr) {
  const a = parseAddr(addr);
  const start = `${addr.replace(/\$/g, "").toUpperCase()}`;
  void a;
  const info = analyze(sheet);
  const cycle = new Set();
  for (const comp of sccs(info)) if (cyclic(comp, info)) comp.forEach((x) => cycle.add(x));
  // Reverse edges, including edges to non-formula cells.
  const readers = new Map();
  for (const [c, { ast }] of info) {
    if (!ast) continue;
    for (const d of refsOf(ast)) {
      if (!readers.has(d)) readers.set(d, []);
      readers.get(d).push(c);
    }
  }
  const reach = new Set();
  const todo = [start];
  while (todo.length) {
    for (const c of readers.get(todo.pop()) ?? []) if (!reach.has(c)) { reach.add(c); todo.push(c); }
  }
  const set = new Set([...reach].filter((c) => c !== start && !cycle.has(c)));
  const key = (c) => { const p = parseAddr(c); return p.row * 1e6 + p.col; };
  const indeg = new Map(), users = new Map();
  for (const c of set) {
    let n = 0;
    for (const d of info.get(c).deps) if (set.has(d)) { n++; if (!users.has(d)) users.set(d, []); users.get(d).push(c); }
    indeg.set(c, n);
  }
  // Binary min-heap by (row, col).
  const heap = [];
  const push = (c) => {
    heap.push(c);
    let i = heap.length - 1;
    while (i > 0) {
      const par = (i - 1) >> 1;
      if (key(heap[par]) <= key(heap[i])) break;
      [heap[par], heap[i]] = [heap[i], heap[par]]; i = par;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let m = i;
        for (const k of [2 * i + 1, 2 * i + 2]) if (k < heap.length && key(heap[k]) < key(heap[m])) m = k;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top;
  };
  for (const [c, n] of indeg) if (n === 0) push(c);
  const out = [];
  while (heap.length) {
    const c = pop();
    out.push(c);
    for (const u of users.get(c) ?? []) { indeg.set(u, indeg.get(u) - 1); if (indeg.get(u) === 0) push(u); }
  }
  return out;
}
