import { test } from "node:test";
import assert from "node:assert/strict";
import {
  createSheet, setCell, getCell, parseFormula, evaluate, refsOf, computeAll, dependents, valueOf,
  formatNumber, toCSV, fromCSV, insertRows, deleteRows, insertCols, deleteCols, sortRange, pivot,
} from "../src/index.mjs";

const ev = (f, cells = {}) => evaluate(parseFormula(f), (a) => cells[a] ?? null);
const sheetOf = (o) => { const s = createSheet(); for (const [k, v] of Object.entries(o)) setCell(s, k, v); return s; };

test("formula", () => {
  assert.equal(ev("-2^2"), 4);
  assert.equal(ev("2^3^2"), 64);
  assert.equal(ev("1/0"), "#DIV/0!");
  assert.equal(ev('"a"+1'), "#VALUE!");
  assert.equal(ev('"a""b"&1'), 'a"b1');
  assert.equal(ev("A1:B2"), "#VALUE!");
  assert.equal(ev("SUM(A1:A3, 1)", { A1: 1, A2: "x", A3: 2 }), 4);
  assert.equal(ev("count(A1:A3, 1)", { A1: 1, A2: "x", A3: "#REF!" }), 2);
  assert.equal(ev("IF(1, 2)"), 2);
  assert.equal(ev("IF(0, 2)"), false);
  assert.equal(ev("ROUND(2.5,0)"), 3);
  assert.equal(ev("ROUND(-1.005,2)"), -1.01);
  assert.equal(ev("ROUND(1234,-2)"), 1200);
  assert.equal(ev("foo(1)"), "#NAME?");
  assert.equal(ev("1<\"a\""), true);
  assert.equal(ev("A1=0"), true);
  assert.deepEqual(refsOf(parseFormula("$B$2+SUM(a1:b2)+A1")), ["B2", "A1", "B1", "A2"]);
  assert.throws(() => parseFormula("1+"), SyntaxError);
  assert.throws(() => parseFormula("(1"), SyntaxError);
});

