  assert.equal(toCSV(createSheet(), null), "");
  assert.equal(toCSV(s, computeAll(s)), '"a,b",x,\n" pad",,2\n');
  const t = fromCSV('a;b\r\n"x;1";=2\r\n');
  assert.equal(getCell(t, "A2"), "x;1");
  assert.equal(getCell(t, "B2"), "'=2");
  assert.equal(getCell(fromCSV("=1", { formulas: true }), "A1"), "=1");
  assert.equal(getCell(fromCSV('"a\n""b"",c"\n,x'), "A1"), 'a\n"b",c');
  assert.equal(getCell(fromCSV('"a\n""b"",c"\n,x'), "B2"), "x");
  assert.throws(() => fromCSV('a\nb,"c\nd'), { message: "unclosed quote at line 2" });
});

test("structure", () => {
  const s = sheetOf({ A1: "1", A2: "2", A3: "=SUM(A1:A2)+$A$3+\"A1\"+LOG10(A1)", B1: "=A2", B2: "=A1:A2" });
  insertRows(s, 2);
  assert.equal(getCell(s, "A4"), '=SUM(A1:A3)+$A$4+"A1"+LOG10(A1)');
  assert.equal(getCell(s, "B3"), "=A3");
  deleteRows(s, 3);
  assert.equal(getCell(s, "B1"), "=#REF!");
  assert.equal(getCell(s, "A3"), '=SUM(A1:A2)+$A$3+"A1"+LOG10(A1)');
  const c = sheetOf({ B1: "=SUM(B1:D1)", C1: "=$D$1", D1: "=C1" });
  deleteCols(c, "C");
  assert.equal(getCell(c, "B1"), "=SUM(B1:C1)");
  assert.equal(getCell(c, "C1"), "=#REF!");
  insertCols(c, "A", 2);
  assert.equal(getCell(c, "D1"), "=SUM(D1:E1)");
  deleteCols(c, "D", 2);
  assert.equal(getCell(c, "D1"), "=SUM(#REF!)");
});

test("table", () => {
  const s = sheetOf({ A1: "n", B1: "v", A2: "b", B2: "3", A3: "A", B3: "1", A4: "", B4: "2", A5: "c", B5: "=B2" });
  sortRange(s, "A1:B5", [{ col: "A" }], { header: true });
  assert.deepEqual([2, 3, 4, 5].map((r) => getCell(s, `A${r}`)), ["A", "b", "c", ""]);
  sortRange(s, "A2:B5", [{ col: "A", desc: true }]);
  assert.deepEqual([2, 3, 4, 5].map((r) => getCell(s, `A${r}`)), ["c", "b", "A", ""]);
  const v = computeAll(sheetOf({ A1: "k", B1: "v", A2: "x", B2: "1", A3: "x", B3: "2", A4: "", B4: "5", A5: "1", B5: "a" }));
  assert.deepEqual(pivot(v, "A1:B5", { rows: "k", value: "v", agg: "sum" }),
    [{ key: 1, value: 0 }, { key: "x", value: 3 }, { key: "(blank)", value: 5 }]);
  assert.throws(() => pivot(v, "A1:B5", { rows: "zz", value: "v", agg: "sum" }), /zz/);
});
